Pseudo:

FUNCTION_BLOCK IPv4Parser
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT;
END_VAR
VAR
    tmp_len : INT;
    tmp_idx : INT;
    tmp_segCount : INT; (* 1..4 current segment *)
    tmp_segVal : UDINT;
    tmp_segHasDigit : BOOL;
    tmp_parseOk : BOOL;
    tmp_ch : BYTE;
    tmp_digit : UDINT;
END_VAR

ipValue := 0;
tmp_len := LEN(ipText);
tmp_idx := 0;
tmp_segCount := 1;
tmp_segVal := 0;
tmp_segHasDigit := FALSE;
tmp_parseOk := TRUE;

WHILE (tmp_idx < tmp_len) DO
    tmp_ch := ipText[tmp_idx];
    IF (tmp_ch >= 48) AND (tmp_ch <= 57) THEN
        tmp_segHasDigit := TRUE;
        tmp_digit := BYTE_TO_UDINT(tmp_ch) - 48;
        tmp_segVal := tmp_segVal * 10 + tmp_digit;
        IF tmp_segVal > 255 THEN
            tmp_parseOk := FALSE;
            EXIT;
        END_IF
    ELSIF tmp_ch = 46 THEN
        IF (NOT tmp_segHasDigit) OR (tmp_segCount >= 4) THEN
            tmp_parseOk := FALSE;
            EXIT;
        END_IF
        ipValue := SHL(ipValue, 8);
        ipValue := ipValue OR tmp_segVal;
        tmp_segCount := tmp_segCount + 1;
        tmp_segVal := 0;
        tmp_segHasDigit := FALSE;
    ELSE
        tmp_parseOk := FALSE;
        EXIT;
    END_IF
    tmp_idx := tmp_idx + 1;
END_WHILE

IF tmp_parseOk THEN
    IF (tmp_segCount <> 4) OR (NOT tmp_segHasDigit) THEN
        tmp_parseOk := FALSE;
    ELSE
        ipValue := SHL(ipValue, 8);
        ipValue := ipValue OR tmp_segVal;
    END_IF
END_IF

IF NOT tmp_parseOk THEN
    ipValue := 0;
END_IF

